/* Renders the case study entirely from window.DATA (generated by agent/pattern_analyzer.py). */
(function () {
  const D = window.DATA, A = D.analysis, R = D.rows, V = D.verification;
  const $ = (s) => document.querySelector(s);
  const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const pct = (n, d) => (d ? Math.round((100 * n) / d) : 0);

  const VERDICTS = ["Ready to build", "Buildable with limitations", "Requires outreach / partnership", "Not currently feasible", "Insufficient evidence"];
  const VSHORT = { "Ready to build": "Ready", "Buildable with limitations": "Limited", "Requires outreach / partnership": "Outreach", "Not currently feasible": "Not feasible", "Insufficient evidence": "Insufficient evidence" };
  const VCOL = { "Ready to build": "#0ca30c", "Buildable with limitations": "#fab219", "Requires outreach / partnership": "#ec835a", "Not currently feasible": "#d03b3b", "Insufficient evidence": "#b9b8b0" };
  const VCHIP = { "Ready to build": "#d8f0d8", "Buildable with limitations": "#fdecc4", "Requires outreach / partnership": "#fbdccf", "Not currently feasible": "#f6d3d3", "Insufficient evidence": "#e7e6e1" };

  // ---------- tooltip ----------
  const tip = $("#tip");
  function bindTip(el, html) {
    el.addEventListener("mousemove", (e) => { tip.innerHTML = html; tip.style.opacity = 1; tip.style.left = Math.min(e.clientX + 14, innerWidth - 340) + "px"; tip.style.top = e.clientY + 14 + "px"; });
    el.addEventListener("mouseleave", () => (tip.style.opacity = 0));
  }

  // ---------- generic horizontal bar chart (single series) ----------
  function hbar(target, entries, { color = "#2a78d6", total = null, labelW = 190 } = {}) {
    const W = 520, rowH = 30, H = entries.length * rowH + 6;
    const max = Math.max(1, ...entries.map((e) => e[1]));
    const plotW = W - labelW - 70;
    const ns = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(ns, "svg");
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    entries.forEach(([label, v, extra], i) => {
      const y = i * rowH + 4, w = Math.max(v ? 3 : 0, (v / max) * plotW);
      const g = document.createElementNS(ns, "g");
      g.innerHTML = `<text x="${labelW - 8}" y="${y + 15}" text-anchor="end">${esc(label)}</text>
        <rect x="${labelW}" y="${y}" width="${plotW}" height="20" fill="transparent"></rect>
        <rect x="${labelW}" y="${y + 3}" width="${w}" height="14" rx="4" fill="${color}"></rect>
        <text class="val" x="${labelW + w + 6}" y="${y + 15}">${v}${total ? ` <tspan class="muted" style="font-weight:400;fill:#7a7974">· ${pct(v, total)}%</tspan>` : ""}</text>`;
      bindTip(g, `<b>${esc(label)}</b><br>${v} app${v === 1 ? "" : "s"}${total ? ` (${pct(v, total)}% of ${total})` : ""}${extra ? "<br><span style='color:#c3c2b7'>" + esc(extra) + "</span>" : ""}`);
      svg.appendChild(g);
    });
    $(target).appendChild(svg);
  }

  // ---------- 01 hero ----------
  const h = A.headline, N = A.n;
  const gatedN = (A.access_counts["Admin approval / app review"] || 0) + (A.access_counts["Enterprise-only"] || 0) + (A.access_counts["Partnership / contact-sales gated"] || 0);
  const topBlocker = Object.entries(A.blocker_counts).filter(([k]) => k !== "None").sort((a, b) => b[1] - a[1])[0];
  const finalStage = V.stages[V.stages.length - 1], firstStage = V.stages[0], midStage = V.stages[1];
  $("#headline").innerHTML = `<b>${h.ready} of ${N} apps could become an agent toolkit today</b>, using self-serve credentials and a documented API. <b>${h.limited}</b> more are buildable with a catch (a paid plan, app review or admin install), and <b>${h.outreach}</b> need a partnership or sales conversation. OAuth2 leads (<b>${h.oauth}</b> apps), but <b>${h.api_key_like}</b> also accept a key or token, so most toolkits can ship with a key path first. The biggest blocker is <b>${esc(topBlocker[0].toLowerCase())}</b> (${topBlocker[1]} apps). On a ${V.sample.apps}-app ground-truth sample (${V.sample.scorable_claims} claims), exact accuracy went from <b>${Math.round(firstStage.accuracy * 100)}%</b> for the naive crawler to <b>${Math.round(midStage.accuracy * 100)}%</b> for the deep crawler, and <b>${Math.round(finalStage.accuracy * 100)}%</b> after Groq adjudication (${Math.round(finalStage.lenient_accuracy * 100)}% counting partial matches). <b>Read the counts above with that error rate in mind:</b> only the ${V.sample.apps} sampled apps were checked by hand (their wrong values are corrected in the dataset); the other ${N - V.sample.apps} are Groq's unreviewed output.`;
  const stats = [
    [N, "apps researched across 10 categories"],
    [V.pages_ok_pass2, `official/doc pages fetched OK (of ${V.pages_fetched_pass2} attempted)`],
    [`${h.self_serve}`, "apps with a self-serve credential path"],
    [`${h.mcp_official}`, "apps with a vendor-published MCP server"],
  ];
  $("#stats").innerHTML = stats.map(([n, l]) => `<div class="card stat"><div class="num">${n}</div><div class="lbl">${l}</div></div>`).join("");

  // stacked verdict bar
  (function () {
    const W = 1000, H = 46, ns = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(ns, "svg"); svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    let x = 0;
    VERDICTS.forEach((v) => {
      const n = A.verdict_counts[v] || 0; if (!n) return;
      const w = (n / N) * W;
      const g = document.createElementNS(ns, "g");
      g.innerHTML = `<rect x="${x + 1}" y="0" width="${Math.max(0, w - 2)}" height="30" rx="4" fill="${VCOL[v]}"></rect>` +
        (w > 70 ? `<text x="${x + 8}" y="20" style="fill:#0b0b0b;font-weight:600">${n} · ${VSHORT[v]}</text>` : "");
      bindTip(g, `<b>${v}</b><br>${n} apps (${pct(n, N)}%)<br><span style="color:#c3c2b7">${esc(R.filter((r) => r.buildability_verdict === v).map((r) => r.app_name).join(", "))}</span>`);
      svg.appendChild(g); x += w;
    });
    $("#verdict-bar").appendChild(svg);
    $("#verdict-legend").innerHTML = VERDICTS.map((v) => `<span><i style="background:${VCOL[v]}"></i>${v} (${A.verdict_counts[v] || 0})</span>`).join("");
  })();

  // ---------- 02 insights ----------
  const byCat = A.by_category;
  const oauthTop = A.oauth_rank.slice(0, 3).map(([c, n, t]) => `${c} (${n}/${t})`).join(", ");
  const keyCats = byCat.slice().sort((a, b) => (b.key_or_token - b.oauth) - (a.key_or_token - a.oauth)).slice(0, 3).map((c) => `${c.category} (${c.key_or_token}/${c.n})`).join(", ");
  const ssTop = A.selfserve_rank.slice(0, 2).map(([c, n, t]) => `${c} ${n}/${t}`).join(", ");
  const ssLow = A.selfserve_rank.slice(-2).map(([c, n, t]) => `${c} ${n}/${t}`).join(", ");
  const insights = [
    ["Auth", `OAuth2 leads, but keys and tokens are everywhere`, `${h.oauth} apps support OAuth2 and ${h.api_key_like} accept an API key, PAT or Basic credential. ${h.multi_auth} support more than one method. OAuth is most common in ${oauthTop}. Keys and tokens dominate in ${keyCats}.`],
    ["Access", `${h.self_serve} of ${N} are self-serve, but "self-serve" often means "paid"`, `${h.self_serve_free} let a developer get credentials free or on a trial/sandbox. ${A.access_counts["Self-serve (paid plan required)"] || 0} need a paid plan first, and ${gatedN} are gated behind app review, enterprise contracts or partnerships. Most self-serve: ${ssTop}. Most gated: ${ssLow}.`],
    ["API surface", `${h.rest} documented REST APIs, ${h.graphql} GraphQL`, `${h.no_api} apps have no documented public REST/GraphQL API (CLI tools, libraries, or nothing public). GraphQL is concentrated in modern SaaS (${R.filter((r) => r.api_type.includes("GraphQL")).map((r) => r.app_name).slice(0, 6).join(", ")}…).`],
    ["MCP", `${h.mcp_official} vendors already ship an official MCP server`, `Another ${h.mcp_third} have only community or third-party MCP servers in the official registry, and ${h.mcp_none} have none found. ${h.llms_txt} publish an llms.txt. Caveat: Groq's MCP field was right on only ${(() => { const p = finalStage.per_field.mcp_available; return p.correct + "/" + (p.correct + p.partial + p.incorrect); })()} sampled apps, below the deep crawler's ${(() => { const p = midStage.per_field.mcp_available; return p.correct + "/" + (p.correct + p.partial + p.incorrect); })()}, so treat these MCP counts as indicative. Even so, vendor MCP is common in dev tools and modern SaaS, so Composio's edge is managed auth and breadth, not mere existence.`],
    ["Blockers", `Top blocker: ${topBlocker[0]}`, Object.entries(A.blocker_counts).filter(([k]) => k !== "None").sort((a, b) => b[1] - a[1]).slice(0, 4).map(([k, v]) => `${k}: ${v}`).join(" · ") + `. Gating is mostly commercial or policy-based (app review, partner programs) rather than technical.`],
    ["Easy wins", `${A.easy_wins.length} apps are ready and free to start`, `Ready to build with free or trial credentials. ${A.easy_no_official_mcp.length} of the ${h.ready} ready apps have no vendor MCP yet, which is where a Composio toolkit adds the most visible value.`],
  ];
  $("#insights").innerHTML = insights.map(([k, t, d]) => `<div class="card insight"><div class="k">${k}</div><div class="t">${esc(t)}</div><div class="d">${esc(d)}</div></div>`).join("");

  hbar("#auth-chart", Object.entries(A.auth_counts).map(([k, v]) => [k, v]), { total: N, labelW: 150 });
  hbar("#access-chart", Object.entries(A.access_counts).filter(([, v]) => v).map(([k, v]) => [k.replace("Self-serve ", "Self-serve "), v]), { total: N, labelW: 220 });
  hbar("#blocker-chart", Object.entries(A.blocker_counts).filter(([k]) => k !== "None").sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, v, R.filter((r) => r.blocker_category === k).map((r) => r.app_name).join(", ")]), { labelW: 200 });

  // ---------- 03 table ----------
  const fill = (sel, vals) => { const s = $(sel); vals.forEach((v) => { const o = document.createElement("option"); o.value = o.textContent = v; s.appendChild(o); }); };
  fill("#f-cat", [...new Set(R.map((r) => r.category))]);
  fill("#f-auth", Object.keys(A.auth_counts));
  fill("#f-access", Object.keys(A.access_counts).filter((k) => A.access_counts[k]));
  fill("#f-verdict", VERDICTS.filter((v) => A.verdict_counts[v]));
  fill("#f-mcp", [...new Set(R.map((r) => r.mcp_available))]);
  let sortKey = "id", sortDir = 1;
  const keyOf = (r, k) => (k === "auth" ? r.auth_methods.join(",") : k === "api" ? r.api_type.join(",") : r[k]);
  function evHtml(r) {
    const groups = {};
    r.evidence.forEach((e) => (groups[e.field] = groups[e.field] || []).push(e));
    return `<div><b>${esc(r.app_name)}</b> · ${esc(r.description)}</div>` +
      (r.notes ? `<div class="ev muted">${esc(r.notes)}</div>` : "") +
      Object.entries(groups).map(([f, es]) => `<div class="ev"><b>${f}</b>${es.map((e) => {
        const cls = e.verification_status.startsWith("Verified") ? "" : e.verification_status.startsWith("Cited") ? "cited" : "fail";
        return `<div style="margin:3px 0 0 10px"><span class="st ${cls}">${esc(e.verification_status)}</span>${esc(e.claim)} <a href="${esc(e.source_url)}" target="_blank" rel="noopener">${esc(e.source_url.replace(/^https?:\/\//, "").slice(0, 80))}</a> <span class="muted">(${e.source_type})</span></div>`;
      }).join("")}</div>`).join("") +
      (r.composio ? `<div class="ev"><b>Composio catalog</b> <span class="muted">(secondary evidence)</span>: ${r.composio.has_toolkit ? `toolkit <code>${esc(r.composio.slug)}</code>, ${esc(r.composio.tools)} tools, auth ${esc((r.composio.auth || []).join(", "))}, match ${esc(r.composio.confidence)}, vs crawler: ${esc(r.composio.agreement)}` : r.composio.rejected ? `catalog match rejected: ${esc(r.composio.rejected)}` : "no toolkit in Composio's catalog"}</div>` : "") +
      `<div class="ev muted">Agent pass-2 said: auth ${esc((r.agent_pass2.auth_methods || []).join(", ") || "—")} · access ${esc(r.agent_pass2.credential_access)} · API ${esc((r.agent_pass2.api_type || []).join(", ") || "—")} · MCP ${esc(r.agent_pass2.mcp_available)} · ${esc(r.agent_pass2.buildability_verdict)} · confidence ${esc(r.confidence)}</div>`;
  }
  function render() {
    const q = $("#q").value.toLowerCase(), c = $("#f-cat").value, au = $("#f-auth").value, ac = $("#f-access").value, ve = $("#f-verdict").value, mc = $("#f-mcp").value;
    const rows = R.filter((r) => (!c || r.category === c) && (!au || r.auth_methods.includes(au)) && (!ac || r.credential_access === ac) && (!ve || r.buildability_verdict === ve) && (!mc || r.mcp_available === mc) &&
      (!q || JSON.stringify([r.app_name, r.category, r.description, r.auth_methods, r.credential_access, r.primary_blocker, r.api_type]).toLowerCase().includes(q)))
      .sort((a, b) => { const x = keyOf(a, sortKey), y = keyOf(b, sortKey); return (x > y ? 1 : x < y ? -1 : 0) * sortDir; });
    $("#count").textContent = `${rows.length} of ${R.length} apps`;
    $("#tbl tbody").innerHTML = rows.map((r) => `<tr class="row">
      <td><div class="app">${esc(r.app_name)}${r.requires_human_review ? '<span class="flag">review</span>' : ""}</div><div class="cat">${esc(r.category)}</div></td>
      <td>${r.auth_methods.map((m) => `<span class="pill">${esc(m)}</span>`).join("") || '<span class="muted">none found</span>'}</td>
      <td>${esc(r.credential_access)}</td>
      <td>${r.api_type.map((m) => `<span class="pill">${esc(m)}</span>`).join("") || '<span class="muted">—</span>'}</td>
      <td>${esc(r.mcp_available)}</td>
      <td><span class="v"><i style="background:${VCOL[r.buildability_verdict]}"></i>${esc(VSHORT[r.buildability_verdict])}</span></td>
      <td class="small">${esc(r.primary_blocker)}</td>
      <td><button class="evbtn" data-id="${r.id}">Evidence (${r.evidence.length})</button></td></tr>
      <tr class="detail" id="d${r.id}" hidden><td colspan="8">${evHtml(r)}</td></tr>`).join("");
  }
  ["#q", "#f-cat", "#f-auth", "#f-access", "#f-verdict", "#f-mcp"].forEach((s) => $(s).addEventListener("input", render));
  $("#tbl thead").addEventListener("click", (e) => { const k = e.target.dataset.k; if (!k) return; sortDir = sortKey === k ? -sortDir : 1; sortKey = k; render(); });
  $("#tbl tbody").addEventListener("click", (e) => { const id = e.target.dataset.id; if (id) { const d = $("#d" + id); d.hidden = !d.hidden; } });
  render();

  // ---------- 04 categories ----------
  const best = byCat.slice().sort((a, b) => b.ready - a.ready)[0], worst = byCat.slice().sort((a, b) => (b.outreach + b.infeasible) - (a.outreach + a.infeasible))[0];
  $("#cat-sub").textContent = `${best.category} is the most agent-ready category (${best.ready}/${best.n} ready to build). ${worst.category} needs the most outreach or further investigation (${worst.outreach + worst.infeasible}/${worst.n}).`;
  (function () {
    const W = 560, rowH = 30, labelW = 210, plotW = W - labelW - 10, ns = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(ns, "svg"); svg.setAttribute("viewBox", `0 0 ${W} ${byCat.length * rowH + 4}`);
    byCat.forEach((c, i) => {
      const y = i * rowH + 4; let x = labelW;
      const t = document.createElementNS(ns, "text"); t.setAttribute("x", labelW - 8); t.setAttribute("y", y + 15); t.setAttribute("text-anchor", "end"); t.textContent = c.category; svg.appendChild(t);
      VERDICTS.forEach((v) => {
        const n = c.verdicts[v].length; if (!n) return; const w = (n / c.n) * plotW;
        const g = document.createElementNS(ns, "g");
        g.innerHTML = `<rect x="${x + 1}" y="${y + 2}" width="${Math.max(0, w - 2)}" height="16" rx="3" fill="${VCOL[v]}"></rect>`;
        bindTip(g, `<b>${esc(c.category)} · ${v}</b><br>${n}/${c.n}: ${esc(c.verdicts[v].join(", "))}`);
        svg.appendChild(g); x += w;
      });
    });
    $("#cat-chart").appendChild(svg);
    $("#cat-legend").innerHTML = VERDICTS.map((v) => `<span><i style="background:${VCOL[v]}"></i>${VSHORT[v]}</span>`).join("");
  })();
  (function () {
    const cols = [["oauth", "OAuth2"], ["key_or_token", "Key/PAT/Basic"], ["self_serve", "Self-serve"], ["gated", "Gated"], ["ready", "Ready"], ["mcp_official", "Official MCP"]];
    const shade = (v, n) => `rgba(42,120,214,${(0.08 + 0.62 * (v / n)).toFixed(2)})`;
    $("#heat").innerHTML = `<tr><th>Category</th>${cols.map(([, l]) => `<th>${l}</th>`).join("")}</tr>` +
      byCat.map((c) => `<tr><td>${esc(c.category)}</td>${cols.map(([k]) => `<td class="hc" style="background:${shade(c[k], c.n)};color:${c[k] / c.n > 0.6 ? "#fff" : "#0b0b0b"}">${c[k]}</td>`).join("")}</tr>`).join("");
  })();

  // ---------- 05 matrix ----------
  (function () {
    let html = `<div></div>` + VERDICTS.map((v) => `<div class="h"><span class="v"><i style="background:${VCOL[v]}"></i>${VSHORT[v]}</span></div>`).join("");
    byCat.forEach((c) => {
      html += `<div class="rowh">${esc(c.category)}</div>`;
      VERDICTS.forEach((v) => {
        const apps = R.filter((r) => r.category === c.category && r.buildability_verdict === v);
        html += `<div class="cell">${apps.map((r) => `<span class="chip" data-id="${r.id}" style="background:${VCHIP[v]};${r.in_verification_sample ? "box-shadow:0 0 0 1.5px #2a78d6 inset" : ""}">${esc(r.app_name)}</span>`).join("")}</div>`;
      });
    });
    $("#bmatrix").innerHTML = html;
    document.querySelectorAll("#bmatrix .chip").forEach((el) => { const r = R.find((x) => x.id == el.dataset.id); bindTip(el, `<b>${esc(r.app_name)}</b><br>${esc(r.auth_methods.join(", ") || "no auth found")} · ${esc(r.credential_access)}<br>Blocker: ${esc(r.primary_blocker)}`); });
  })();

  // ---------- 06 run stats ----------
  $("#runstats").innerHTML = [
    `${V.applications_total} apps × 2 crawler passes (5 checkpointed batches of 20, 8 workers), then ${V.applications_adjudicated} Groq adjudications (checkpointed per app)`,
    `${V.pages_fetched_pass2} page fetches attempted in pass 2; ${V.pages_ok_pass2} returned usable content`,
    `${V.applications_with_fetched_official_evidence} apps have at least one claim backed by an official page the agent fetched`,
    `${V.distinct_sources_cited} distinct source URLs cited in the final dataset`,
    `${V.claims_changed_crawler_to_groq} field values changed by Groq across ${V.apps_changed_crawler_to_groq} apps (crawler → final, logged in the verification report)`,
    `Groq models used: ${Object.entries(V.models_used).map(([m, n]) => m + " (" + n + " apps)").join(", ")}`,
    `${V.tool_calls.total} tool calls requested by Groq and executed by Python (${Object.entries(V.tool_calls.by_tool).map(([t, n]) => t + ": " + n).join(", ")}); ${V.tool_calls.failed} failed`,
    `${V.unsupported_citations_dropped} citations dropped by the validator because the URL was not among the fetched pages`,
    `${V.apps_requiring_human_review} apps still flagged for human review`,
  ].map((s) => `<li>${esc(s)}</li>`).join("");

  // ---------- 06b composio ----------
  (function () {
    const C = D.composio; if (!C) { $("#composio").hidden = true; return; }
    const cc = C.connectivity, x = cc.catalog_cross_check, ex = cc.tool_execution;
    $("#cmp-sub").textContent = `Composio's live catalog lists ${x.catalog_toolkits} toolkits. ${x.apps_with_toolkit} of our 100 apps already have one, so they're existing coverage to maintain. ${x.apps_without_toolkit.length} have none: ${x.apps_without_toolkit.join(", ")}. ${C.no_toolkit_ready.length} of those are buildable now (${C.no_toolkit_ready.join(", ")}), which makes them the clearest net-new toolkit candidates.`;
    $("#cmp-calls").innerHTML = `<tr><th>SDK step</th><th>Result</th></tr>` + cc.steps.map((s) => `<tr><td><code>${esc(s.step)}</code></td><td class="${s.ok ? "ok" : "bad"}">${s.ok ? "OK" : esc(s.detail)}</td></tr>`).join("") +
      (ex && !cc.steps.some((s) => s.step.startsWith("session.execute")) ? `<tr><td><code>session.execute(${esc(ex.tool)})</code></td><td class="ok">OK (HTTP ${esc((ex.http.find((h) => h.includes("/execute")) || "").match(/HTTP\/1.1 (\d+)/)?.[1] || "?")})</td></tr>` : "");
    $("#cmp-exec").innerHTML = ex ? `Executed <code>${esc(ex.tool)}</code>, which is ${esc(ex.why_safe)}. GitHub tools were <b>not</b> run: ${esc((ex.github_connection || {}).note || "no app account connected.")} SDK ${esc(cc.sdk_version)}, telemetry ${cc.telemetry_enabled ? "on" : "off"}.` : "";
    hbar("#cmp-agree", Object.entries(x.auth_agreement_vs_crawler).sort((a, b) => b[1] - a[1]), { total: 100, labelW: 180 });
    $("#cmp-limits").innerHTML = cc.limitations.map((l) => `<li>${esc(l)}</li>`).join("");
    const G = D.groq || {};
    if (G.connectivity) {
      const gc = G.connectivity, gi = G.integration || {};
      $("#groq-calls").innerHTML = `<tr><th>Groq check</th><th>Result</th></tr>` + gc.steps.map((s) => `<tr><td><code>${esc(s.step)}</code></td><td class="${s.ok ? "ok" : "bad"}">${s.ok ? "OK" : "FAILED"}${typeof s.detail === "string" ? " · " + esc(s.detail) : ""}</td></tr>`).join("") +
        (gi.checks || []).map((c) => `<tr><td>${esc(c.check)}</td><td class="${c.ok ? "ok" : "bad"}">${c.ok ? "PASS" : "FAIL"}</td></tr>`).join("");
      $("#groq-trace").innerHTML = gi.tool_trace ? `Round trip: Groq (<code>${esc(gi.model)}</code>) requested <code>${esc(gi.tool_trace.map((t) => t.tool).join(", "))}</code>, Python executed it via the Composio session (${gi.tool_trace.map((t) => t.ms + " ms").join(", ")}), and Groq answered: “${esc(gi.final_answer)}”` : "";
    }
  })();

  // ---------- 07 verification ----------
  $("#ver-sub").textContent = `Sample: ${V.sample.apps} apps (3 per category, drawn with a fixed random seed before any LLM run). ${V.sample.scorable_claims} claims scored (auth, API type, credential access, MCP, verdict); ${V.sample.excluded_claims} left unscored because the official evidence didn't settle them. Ground truth: ${V.sample.reviewer}. Every stage is scored against the same truth. "Partial" means, for example, the right auth class but a missing extra one, or self-serve but the wrong tier.`;
  hbar("#acc-chart", V.stages.map((s) => [s.stage.split(":")[0], Math.round(s.accuracy * 100), s.stage]), { color: "#2a78d6", labelW: 80 });
  document.querySelectorAll("#acc-chart .val").forEach((t) => (t.textContent += "%"));
  $("#acc-note").innerHTML = V.stages.concat([V.composio_auth_reference]).map((s) => `<b>${esc(s.stage)}</b>: ${s.correct}/${s.claims_scored} correct, ${s.partial} partial, ${s.incorrect} wrong (${s.apps_covered} apps)`).join("<br>");
  const rowsV = [
    ["Applications researched (crawler)", V.applications_total],
    ["Applications adjudicated by Groq", V.applications_adjudicated],
    ["Applications with evidence", V.applications_with_evidence],
    ["…with an official page fetched by the agent", V.applications_with_fetched_official_evidence],
    ["Initial accuracy (pass 1, naive crawler)", `${Math.round(firstStage.accuracy * 100)}% (${firstStage.correct}/${firstStage.claims_scored})`],
    ["Deep crawler accuracy (pass 2)", `${Math.round(midStage.accuracy * 100)}% (${midStage.correct}/${midStage.claims_scored})`],
    ["Final accuracy (Groq adjudication)", `${Math.round(finalStage.accuracy * 100)}% (${finalStage.correct}/${finalStage.claims_scored})`],
    ["Final, counting partial matches", `${Math.round(finalStage.lenient_accuracy * 100)}%`],
    ["Field values changed crawler → Groq (all apps)", V.claims_changed_crawler_to_groq],
    ["Unsupported citations dropped", V.unsupported_citations_dropped],
    ["Apps requiring human review", V.apps_requiring_human_review],
    ["Pages fetched (pass 2)", `${V.pages_ok_pass2} OK / ${V.pages_fetched_pass2}`],
    ["Distinct sources cited", V.distinct_sources_cited],
  ];
  $("#ver-table").innerHTML = rowsV.map(([k, v]) => `<tr><td>${esc(k)}</td><td style="text-align:right"><b>${esc(v)}</b></td></tr>`).join("");
  const fields = Object.keys(firstStage.per_field);
  $("#field-table").innerHTML = `<tr><th>Field</th>${V.stages.map((s) => `<th>${esc(s.stage.split(":")[0])}</th>`).join("")}</tr>` +
    fields.map((f) => `<tr><td>${f}</td>${V.stages.map((s) => { const p = s.per_field[f], n = p.correct + p.partial + p.incorrect; return `<td class="hc">${pct(p.correct, n)}% <span class="muted" style="font-weight:400">(${p.correct}/${n}, ${p.partial} partial)</span></td>`; }).join("")}</tr>`).join("");
  const GA = V.groq_attempts || { failed_attempts: 0, apps_with_failed_attempt: 0 };
  const tc = V.tool_calls.by_tool;
  $("#stage4-text").innerHTML = `Groq reads each app's evidence (${Object.entries(V.models_used).map(([m, n]) => `<code>${esc(m.replace("openai/", ""))}</code> for ${n} apps`).join("; ")}; the fallback took over when the primary model's free daily token cap ran out). ` +
    `It may call read-only tools: re-read a fetched official page, or list Composio toolkit tools and schemas. In the full run it chose ${Object.entries(tc).map(([t, n]) => `<code>${esc(t)}</code> ${n}×`).join(", ")}${Object.keys(tc).some((t) => /composio/i.test(t)) ? "" : "; it never chose a Composio tool, so that path is shown by the round-trip test (06b)"}. ` +
    `Then it emits strict-schema JSON, checked again in Python before an app counts as done. Groq rejected ${GA.failed_attempts} attempts across ${GA.apps_with_failed_attempt} apps; ${(V.applications_unresolved || []).length ? (V.applications_unresolved.length + " remain unresolved") : "all succeeded on retry"}. Citations not among the fetched pages are dropped.`;
  const BM = V.groq_by_model || {};
  $("#model-table").innerHTML = `<tr><th>Model</th><th>Apps (all)</th><th>Sample apps</th><th>Exact</th><th>+ partial</th><th>Review-flag rate</th><th>"Insufficient evidence" rate</th><th>Retried</th></tr>` +
    Object.entries(BM).map(([m, s]) => `<tr><td><code>${esc(m)}</code></td><td>${s.apps_adjudicated_total}</td><td>${s.apps_covered}</td>` +
      `<td>${s.claims_scored ? Math.round(s.accuracy * 100) + "% (" + s.correct + "/" + s.claims_scored + ")" : "n/a"}</td>` +
      `<td>${s.claims_scored ? Math.round(s.lenient_accuracy * 100) + "%" : "n/a"}</td>` +
      `<td>${Math.round(s.review_flag_rate_all_apps * 100)}%</td><td>${Math.round(s.insufficient_evidence_rate_all_apps * 100)}%</td><td>${s.retried_apps}</td></tr>`).join("");
  $("#model-caveat").textContent = V.groq_by_model_caveat || "";
  const RC = V.review_corrections || [];
  $("#corr-sub").textContent = `${RC.length} sampled field values where Groq disagreed with the ground truth. The final dataset uses the reviewed value, but the accuracy figures above score Groq's original answer.` +
    ((V.applications_unresolved || []).length ? ` Unresolved apps (Groq failed twice, no record written): ${V.applications_unresolved.map((u) => u.app).join(", ")}.` : "");
  $("#corr-table").innerHTML = `<tr><th>App</th><th>Field</th><th>Groq said</th><th>Reviewed value</th></tr>` +
    RC.map((c) => `<tr><td>${esc(c.app)}</td><td>${c.field}</td><td class="bad">${esc([].concat(c.groq ?? "—").join(", ") || "—")}</td><td class="ok">${esc([].concat(c.reviewed).join(", "))}</td></tr>`).join("");
  const fm = finalStage.misses;
  $("#final-misses").innerHTML = fm.length ? `<table class="miss"><tr><th>App</th><th>Field</th><th>Result</th><th>Final said</th><th>Ground truth</th></tr>${fm.map((m) => `<tr><td>${esc(m.app)}</td><td>${m.field}</td><td>${m.verdict}</td><td class="bad">${esc([].concat(m.predicted).join(", "))}</td><td class="ok">${esc([].concat(m.truth).join(", "))}</td></tr>`).join("")}</table>` : "None on the sample.";
  const pm = midStage.misses;
  $("#p2-misses").innerHTML = `<tr><th>App</th><th>Field</th><th>Result</th><th>Crawler (pass 2) said</th><th>Ground truth</th></tr>` + pm.map((m) => `<tr><td>${esc(m.app)}</td><td>${m.field}</td><td>${m.verdict}</td><td class="bad">${esc([].concat(m.predicted ?? "—").join(", ") || "—")}</td><td class="ok">${esc([].concat(m.truth).join(", "))}</td></tr>`).join("");

  // ---------- 08 recs ----------
  const list = (a) => a.map((x) => esc(typeof x === "string" ? x : x.app)).join(", ");
  const recs = [
    ["Ship first: easy wins", `Ready to build with free or trial credentials (${A.easy_wins.length}): ${list(A.easy_wins)}.`],
    ["Prioritize: ready, but no vendor MCP yet", `Here a Composio toolkit is the agent-native path, not a duplicate of the vendor's own MCP (${A.easy_no_official_mcp.length}): ${list(A.easy_no_official_mcp)}.`],
    ["Open partner conversations", `Need a partner program, enterprise contract or sales contact (${A.partnerships.length}): ${A.partnerships.map((p) => `<b>${esc(p.app)}</b> (${esc(p.blocker)})`).join("; ")}.`],
    ["Good API, hard credentials", `Documented REST/GraphQL but gated access (${A.good_api_hard_access.length}): ${list(A.good_api_hard_access)}. The engineering is easy; the work is business development and app-review submissions, which can run in parallel.`],
    ["Investigate further", `No public API found, or not enough evidence (${A.investigate.length}): ${A.investigate.map((p) => `<b>${esc(p.app)}</b> (${esc(p.why)})`).join("; ")}.`],
    ["Process: what to automate next", `The naive agent was right on ${Math.round(firstStage.accuracy * 100)}% of claims and the deep loop on ${Math.round(midStage.accuracy * 100)}%. Credential access is the hardest field to automate, because it lives in pricing pages and partner terms, not API references. Next steps: add a pricing-page fetch, add the Composio toolkit lookup to skip apps that already exist, and re-run monthly with the cache to diff what changed.`],
  ];
  $("#recs-grid").innerHTML = recs.map(([t, d]) => `<div class="card insight"><div class="t">${t}</div><div class="d">${d}</div></div>`).join("");
})();
